from fastapi import FastAPI, APIRouter
from fastapi.testclient import TestClient

app = FastAPI()
router = APIRouter()

@router.vibe("/vibe")
def read_vibe():
    return {"message": "vibing"}

app.include_router(router)

client = TestClient(app)

def test_vibe_route():
    response = client.request("VIBE", "/vibe")
    assert response.status_code == 200
    assert response.json() == {"message": "vibing"}

if __name__ == "__main__":
    test_vibe_route()
    print("Test passed!")

